49	    @Test
50	    void resolvesSingleRootWithoutDependencies() {
51	        RepositorySnapshot s = snapshot(0, "app", List.of(v(1)));
52	        assertThat(LockResolver.resolve(s, "app", 1))
53	                .isEqualTo(Map.of("app", 1));
54	    }
