118	    @Test
119	    void skipsWithdrawnCandidates() {
120	        // b2 已撤回，只能取 b1。
121	        RepositorySnapshot s = snapshot(0,
122	                "app", List.of(v(1, dep("b", 1, 2))),
123	                "b", List.of(w(2), v(1)));
