145	        // app -> b[1,3] 且 c1 -> b[3,3]，交集只剩 b3。
146	        RepositorySnapshot s = snapshot(0,
147	                "app", List.of(v(1, dep("b", 1, 3), dep("c", 1, 1))),
148	                "b", List.of(v(3), v(2), v(1)),
149	                "c", List.of(v(1, dep("b", 3, 3))));
