154	    @Test
155	    void emptyRangeIntersectionIsInfeasible() {
156	        // app -> b[1,2] 且 c1 -> b[3,3]，交集为空。
157	        RepositorySnapshot s = snapshot(0,
158	                "app", List.of(v(1, dep("b", 1, 2), dep("c", 1, 1))),
