    private static List<Integer> parseVersions(String versions) {
        if (versions == null || versions.isEmpty()) {
            return null;
        }
        List<Integer> result = new ArrayList<>();
        for (String part : versions.split(",")) {
            result.add(Integer.valueOf(part));
        }
        return result;
    }
