    @Test
    void detailedBlockersAreDeduplicatedAndSortedByName() {
        // app -> a[1,1] 且 b[1,1]；a1 -> c[2,2]，b1 -> c[2,2]；c 只有 c1。
        // 两个分支都在 c 上失败，阻塞项应去重且按名称排序。
        RepositorySnapshot s = snapshot(0,
                "app", List.of(v(1, dep("a", 1, 1), dep("b", 1, 1))),
                "a", List.of(v(1, dep("c", 2, 2))),
                "b", List.of(v(1, dep("c", 2, 2))),
                "c", List.of(v(1)));

        LockResolver.Resolution detailed = LockResolver.resolveDetailed(s, "app", 1);
        assertThat(detailed.feasible()).isFalse();
        assertThat(detailed.blockers())
                .allMatch(blocker -> blocker.name().equals("c"))
                .hasSize(1);
        assertThat(detailed.blockers().get(0).reason())
                .isEqualTo(LockResolver.REASON_MISSING_VERSION);
        assertThat(detailed.blockers().get(0).versions()).containsExactly(2);
    }
}

